<x-theme::section data-theme-block="{{ $definition['type'] }}"><x-theme::container>@if(!empty($settings['title']))<x-theme::heading :level="2" class="theme-section-title">{{ $settings['title'] }}</x-theme::heading>@endif<div class="theme-blog-grid">@forelse($posts as $post)<article class="theme-blog-card">@if($post->logo_url)<img src="{{ $post->logo_url }}" alt="{{ $post->name }}" loading="lazy">@else<div class="theme-blog-card__placeholder" aria-hidden="true">◇</div>@endif<div><h3><a href="{{ route('articles.show', $post->slug) }}">{{ $post->name }}</a></h3>@if($post->description ?? null)<p>{{ $post->description }}</p>@endif</div></article>@empty<x-theme::empty-state title="نوشته‌ای برای نمایش وجود ندارد" />@endforelse</div></x-theme::container></x-theme::section>
